class Solution {
public:
    TreeNode* convertBST(TreeNode* root) {
        int sum = 0;
        TreeNode* cur = root;
        while (cur != nullptr) {
            if (cur->right == nullptr) {
                cur->val += sum;
                sum = cur->val;
                cur = cur->left;
            } else {
                TreeNode* succ = cur->right;
                while (succ->left != nullptr && succ->left != cur) {
                    succ = succ->left;
                }
                if (succ->left == nullptr) {
                    succ->left = cur;
                    cur = cur->right;
                } else {
                    succ->left = nullptr;
                    cur->val += sum;
                    sum = cur->val;
                    cur = cur->left;
                }
            }
        }
        return root;
    }
};
